import re, sys

UNSOURCED_NUM = re.compile(r"\d+\.?\d*\s*%?")
CITATION      = re.compile(
    r"\[\d+\]|\(source\)|per \w+\.(?:csv|json|md)"
)
OVERWARRANT   = re.compile(
    r"\b(proves?|demonstrates?|shows?|conclusively)\b",
    re.IGNORECASE
)
FIGURE_LINK   = re.compile(
    r"(?:Fig\.|Table|figure|chart)\s*\d+", re.IGNORECASE
)

for i, line in enumerate(lines, 1):
    if UNSOURCED_NUM.search(line) and not CITATION.search(line):
        print(f"L{i} UNSOURCED NUMBER: {line.strip()}")
    if OVERWARRANT.search(line) and not FIGURE_LINK.search(line):
        print(f"L{i} OVER-WARRANTED VERB: {line.strip()}")
